// NATIVE bridge: binds the browser-process PageHandler over Mojo using the
// bindings generated by the Chromium build from
// browser/integration/justslide/webui/justslide_shell.mojom. The generated
// module is served by the WebUI data source at runtime; it is not bundled.
import type { ColorMode, OpenedBy, SecurityLevel, ShellBridge, ShellSnapshot, WorkspaceIcon, ProfileKind, AgentState } from './types';

/** Shape of the generated `justslide_shell.mojom-webui.js` module that this file relies on. */
interface GeneratedModule {
  PageHandlerFactory: { getRemote(): { createPageHandler(page: unknown, handler: unknown): void } };
  PageHandlerRemote: new () => Record<string, (...a: unknown[]) => any> & { $: { bindNewPipeAndPassReceiver(): unknown } };
  PageCallbackRouter: new () => { $: { bindNewPipeAndPassRemote(): unknown }; snapshotChanged: { addListener(fn: (s: any) => void): number }; focusAddressField: { addListener(fn: () => void): number } };
}

// Must match the enum declaration order in justslide_shell.mojom.
const SECURITY: SecurityLevel[] = ['unknown', 'secure', 'insecure', 'internal', 'dangerous'];
const OPENED_BY: OpenedBy[] = ['user', 'agent', 'extension', 'restore', 'popup'];
const COLOR: ColorMode[] = ['system', 'light', 'dark'];
const ICON: WorkspaceIcon[] = ['personal', 'chatgpt', 'claude-code', 'agent', 'work', 'generic'];
const PROFILE: ProfileKind[] = ['personal', 'agent-isolated'];
const AGENT: AgentState[] = ['active', 'paused', 'revoked'];

const urlOf = (u: { url?: string } | undefined) => u?.url ?? '';

export function fromMojo(s: any): ShellSnapshot {
  return {
    revision: Number(s.revision),
    selectedWorkspaceId: s.selectedWorkspaceId,
    activeTabId: s.activeTabId,
    sidebarCollapsed: s.sidebarCollapsed,
    displayUrl: s.displayUrl,
    securityLevel: SECURITY[s.securityLevel] ?? 'unknown',
    origin: s.origin,
    canGoBack: s.canGoBack,
    canGoForward: s.canGoForward,
    workspaces: s.workspaces.map((w: any) => ({ id: w.id, name: w.name, icon: ICON[w.icon] ?? 'generic', profileKind: PROFILE[w.profileKind] ?? 'personal', agentOwned: w.agentOwned })),
    tabs: s.tabs.map((t: any) => ({ id: t.id, workspaceId: t.workspaceId, url: urlOf(t.url), title: t.title, pinned: t.pinned, loading: t.loading, active: t.active, openedBy: OPENED_BY[t.openedBy] ?? 'user', crashed: t.crashed, audible: t.audible, hasError: t.hasError })),
    favorites: s.favorites.map((f: any) => ({ id: f.id, url: urlOf(f.url), title: f.title })),
    agents: s.agents.map((a: any) => ({ grantId: a.grantId, clientName: a.clientName, workspaceIds: a.workspaceIds, state: AGENT[a.state] ?? 'revoked', lastAction: a.lastAction, pending: a.pending.map((p: any) => ({ ...p })) })),
    colorMode: COLOR[s.colorMode] ?? 'system',
    backdropColor: s.backdropColor,
  };
}

export async function connectMojoBridge(moduleUrl = './justslide_shell.mojom-webui.js'): Promise<ShellBridge> {
  // Non-literal specifier: the bundler leaves this import to the runtime.
  const mod = (await import(/* @vite-ignore */ moduleUrl)) as GeneratedModule;
  const handler = new mod.PageHandlerRemote();
  const router = new mod.PageCallbackRouter();
  mod.PageHandlerFactory.getRemote().createPageHandler(router.$.bindNewPipeAndPassRemote(), handler.$.bindNewPipeAndPassReceiver());
  let snap: ShellSnapshot | null = null;
  const listeners = new Set<() => void>();
  const focus = new Set<() => void>();
  const apply = (s: any) => {
    const next = fromMojo(s);
    if (snap && next.revision <= snap.revision) return; // ordered, ignore stale
    snap = next;
    listeners.forEach(l => l());
  };
  router.snapshotChanged.addListener(apply);
  router.focusAddressField.addListener(() => focus.forEach(l => l()));
  handler.getSnapshot().then(({ snapshot }: any) => apply(snapshot));
  const call = (name: string) => (...args: unknown[]) => { handler[name](...args); };
  return {
    kind: 'native',
    getSnapshot: () => snap,
    subscribe: l => { listeners.add(l); return () => { listeners.delete(l); }; },
    onFocusAddressField: l => { focus.add(l); return () => { focus.delete(l); }; },
    navigateFromInput: call('navigateFromInput'),
    goBack: call('goBack'),
    goForward: call('goForward'),
    reload: call('reload'),
    toggleSidebar: call('toggleSidebar'),
    selectTab: call('selectTab'),
    createTab: call('createTab'),
    closeTab: call('closeTab'),
    reopenClosedTab: call('reopenClosedTab'),
    setTabPinned: call('setTabPinned'),
    moveTab: call('moveTab'),
    selectWorkspace: call('selectWorkspace'),
    createWorkspace: call('createWorkspace'),
    renameWorkspace: call('renameWorkspace'),
    addFavoriteForActiveTab: call('addFavoriteForActiveTab'),
    removeFavorite: call('removeFavorite'),
    moveFavorite: call('moveFavorite'),
    openFavorite: call('openFavorite'),
    resolvePendingRequest: call('resolvePendingRequest'),
    setAgentPaused: call('setAgentPaused'),
    revokeAgent: call('revokeAgent'),
    setColorMode: (m: ColorMode) => handler.setColorMode(COLOR.indexOf(m)),
    setBackdropColor: call('setBackdropColor'),
    showPairingDialog: call('showPairingDialog'),
  };
}
